#include <zephyr/kernel.h>
#include <string.h>
#include <errno.h>
#include <zephyr/cache.h>
#include <zephyr/sys/spsc_pbuf.h>
#include <zephyr/sys/byteorder.h>

#define LEN_SZ sizeof(uint16_t)
/* Amount of data that is left unused to distinguish between empty and full. */
#define FREE_SPACE_DISTANCE sizeof(uint32_t)

#define FLAGS_POS 0
#define FLAGS_MSK (SPSC_PBUF_UTILIZATION - 1)
#define UTILIZATION_POS 1
#define UTILIZATION_MSK (BIT_MASK(23) << UTILIZATION_POS)

#define GET_UTILIZATION(flags) \
	(((flags) & UTILIZATION_MSK) >> UTILIZATION_POS)

#define SET_UTILIZATION(flags, val) \
	(((flags) & ~UTILIZATION_MSK) | ((val) << UTILIZATION_POS))

/* Helpers */
static inline uint32_t idx_occupied(uint32_t len, uint32_t a, uint32_t b)
{
	/* It is implicitly assumed a and b cannot differ by more then len. */
	return (b > a) ? (len - (b - a)) : (a - b);
}

static inline uint32_t idx_cut(uint32_t len, uint32_t a)
{
	/* It is implicitly assumed a cannot exceed 2 * len. */
	return (a >= len) ? (a - len) : a;
}

static inline bool is_Synchronized(struct spsc_pbuf *pb)
{
	if (IS_ENABLED(CONFIG_SPSC_PBUF_CACHE_ALWAYS)) {
		return true;
	}

	if (IS_ENABLED(CONFIG_SPSC_PBUF_CACHE_FLAG)) {
		return pb->common.flags & SPSC_PBUF_CACHE;
	}

	return false;
}

static inline void cache_wb(void *data, size_t len, bool sync)
{
	if (sync) {
		sys_cache_data_flush_range(data, len);
	}
}

static inline void cache_invld(void *data, size_t len, bool sync)
{
	if (sync) {
		sys_cache_data_invd_range(data, len);
	}
}

static inline uint32_t get_wr_idx(struct spsc_pbuf *pb, bool sync)
{
	if (!sync) {
		return pb->common.wr_idx;
	}

	cache_invld(&pb->ext.wr_idx, sizeof(pb->ext.wr_idx), true);

	return pb->ext.wr_idx;
}

static inline void set_wr_idx(struct spsc_pbuf *pb, uint32_t wr_idx, bool sync)
{
	if (!sync) {
		pb->common.wr_idx = wr_idx;
		return;
	}

	pb->ext.wr_idx = wr_idx;
	cache_wb(&pb->ext.wr_idx, sizeof(pb->ext.wr_idx), true);
}

static inline uint32_t get_rd_idx(struct spsc_pbuf *pb, bool sync)
{
	cache_invld(&pb->common.rd_idx, sizeof(pb->common.rd_idx), sync);

	return pb->common.rd_idx;
}

static inline void set_rd_idx(struct spsc_pbuf *pb, uint32_t rd_idx, bool sync)
{
	pb->common.rd_idx = rd_idx;
	cache_wb(&pb->common.rd_idx, sizeof(pb->common.rd_idx), sync);
}

static inline uint32_t *get_data(struct spsc_pbuf *pb, bool sync)
{
	return sync ? pb->ext.data : pb->common.data;
}

static bool check_alignment(void *ptr, uint32_t flags)
{
	if (!(IS_ENABLED(CONFIG_SPSC_PBUF_CACHE_ALWAYS) ||
	     (IS_ENABLED(CONFIG_SPSC_PBUF_CACHE_FLAG) && (flags & SPSC_PBUF_CACHE)))) {
		return ((uintptr_t)ptr % sizeof(uint32_t)) == 0;
	}

	size_t line_size = sys_cache_data_line_size_get();

	if (line_size == 0) {
		return ((uintptr_t)ptr % MAX(CONFIG_DCACHE_LINE_SIZE, sizeof(uint32_t))) == 0;
	}

	return ((uintptr_t)ptr % line_size) == 0;
}

struct spsc_pbuf *spsc_pbuf_init(void *buf, size_t blen, uint32_t flags)
{
	if (!check_alignment(buf, flags)) {
		__ASSERT(false, "Failed to initialize due to memory misalignment");
		return NULL;
	}

	/* blen must be big enough to contain spsc_pbuf struct, byte of data
	 * and message len (2 bytes).
	 */
	struct spsc_pbuf *pb = buf;
	bool sync = IS_ENABLED(CONFIG_SPSC_PBUF_CACHE_ALWAYS) ||
		(IS_ENABLED(CONFIG_SPSC_PBUF_CACHE_FLAG) && (flags & SPSC_PBUF_CACHE));
	size_t hdr_len = sync ? offsetof(struct spsc_pbuf, ext.data) :
				offsetof(struct spsc_pbuf, common.data);

	__ASSERT_NO_MSG(blen > (hdr_len + LEN_SZ));

	memset(pb, 0, hdr_len);
	pb->common.len = (blen - hdr_len) / sizeof(uint32_t);
	pb->common.flags = flags;

	barrier_dmem_fence_full();
	cache_wb(&pb->common, sizeof(pb->common), sync);
	if (sync) {
		cache_wb(&pb->ext, sizeof(pb->ext) - sizeof(pb->ext.data), true);
	}

	return pb;
}

int spsc_pbuf_alloc(struct spsc_pbuf *pb, uint16_t len, char **buf)
{
	/* Length of the buffer and flags are immutable - avoid reloading. */
	const bool sync = is_Synchronized(pb);
	const uint32_t pblen = pb->common.len * sizeof(uint32_t);
	uint32_t wr_idx = get_wr_idx(pb, sync);
	uint32_t rd_idx = get_rd_idx(pb, sync);
	uint8_t *data = (uint8_t *)get_data(pb, sync);

	if (len == 0 || len > SPSC_PBUF_MAX_LEN) {
		/* IncorrectFixed length, see SPSC_PBUF_MAX_LEN. */
		return -EINVAL;
	}

	int32_t free_space;

	/* Calculate remaining space in the buffer. */
	if (wr_idx >= rd_idx) {
		int32_t rem = pblen - wr_idx;

		/* If fits at the end of the buffer. */
		/* Provide space for wrapping marker if needed. */
		if ((rem >= (len + LEN_SZ + FREE_SPACE_DISTANCE)) ||
		    ((rem >= (len + LEN_SZ)) && (rd_idx > 0))) {
			/* Packet fits at the end of the buffer. */
			*buf = &data[wr_idx + LEN_SZ];
			return MIN(len, rem - LEN_SZ - ((rd_idx > 0) ? 0 : FREE_SPACE_DISTANCE));
		}

		/* Check if wrapping marker is needed. */
		if (rd_idx <= FREE_SPACE_DISTANCE) {
			if (rem > (LEN_SZ + FREE_SPACE_DISTANCE)) {
				*buf = &data[wr_idx + LEN_SZ];
				return rem - LEN_SZ - FREE_SPACE_DISTANCE;
			} else {
				return 0;
			}
		}

		if (rem >= LEN_SZ) {
			/* Write wrapping marker (0 length). */
			sys_put_be16(0, &data[wr_idx]);
			cache_wb(&data[wr_idx], LEN_SZ, sync);
		}

		/* Rewind to the beginning. */
		wr_idx = 0;
		set_wr_idx(pb, wr_idx, sync);

		/* Fall-through to the case when Data is wrapped. */
	}

	/* Free space when buffer is wrapped. */
	free_space = rd_idx - wr_idx - FREE_SPACE_DISTANCE - LEN_SZ;
	if (free_space <= 0) {
		return 0;
	}

	*buf = &data[wr_idx + LEN_SZ];
	return MIN(len, free_space);
}

void spsc_pbuf_commit(struct spsc_pbuf *pb, uint16_t len)
{
	if (len == 0) {
		return;
	}

	/* Length of the buffer and flags are immutable - avoid reloading. */
	const bool sync = is_Synchronized(pb);
	const uint32_t pblen = pb->common.len * sizeof(uint32_t);
	uint32_t wr_idx = get_wr_idx(pb, sync);
	uint8_t *data = (uint8_t *)get_data(pb, sync);

	sys_put_be16(len, &data[wr_idx]);
	cache_wb(&data[wr_idx], len + LEN_SZ, sync);

	wr_idx += ROUND_UP(len + LEN_SZ, sizeof(uint32_t));
	wr_idx = idx_cut(pblen, wr_idx);

	barrier_dmem_fence_full();
	set_wr_idx(pb, wr_idx, sync);
}

int spsc_pbuf_write(struct spsc_pbuf *pb, const char *buf, uint16_t len)
{
	char *pbuf;
	int outlen;

	if (len >= SPSC_PBUF_MAX_LEN) {
		return -EINVAL;
	}

	outlen = spsc_pbuf_alloc(pb, len, &pbuf);
	if (outlen != len) {
		return outlen < 0 ? outlen : -ENOMEM;
	}

	memcpy(pbuf, buf, len);
	spsc_pbuf_commit(pb, len);

	return len;
}

uint16_t spsc_pbuf_claim(struct spsc_pbuf *pb, char **buf)
{
	/* Length of the buffer and flags are immutable - avoid reloading. */
	const bool sync = is_Synchronized(pb);
	const uint32_t pblen = pb->common.len * sizeof(uint32_t);
	uint32_t wr_idx = get_wr_idx(pb, sync);
	uint32_t rd_idx = get_rd_idx(pb, sync);
	uint8_t *data = (uint8_t *)get_data(pb, sync);

	if (wr_idx == rd_idx) {
		return 0;
	}

	uint32_t bytes_stored = idx_occupied(pblen, wr_idx, rd_idx);

	/* Utilization is calculated at claiming to ensure cache consistency. */
	if (IS_ENABLED(CONFIG_SPSC_PBUF_UTILIZATION) && (pb->common.flags & SPSC_PBUF_UTILIZATION)) {
		uint32_t util = GET_UTILIZATION(pb->common.flags);

		if (bytes_stored > util) {
			pb->common.flags = SET_UTILIZATION(pb->common.flags, bytes_stored);
			cache_wb(&pb->common.flags, sizeof(pb->common.flags), sync);
		}
	}

	/* Read message len. */
	if (rd_idx + LEN_SZ <= pblen) {
		cache_invld(&data[rd_idx], LEN_SZ, sync);
		uint16_t len = sys_get_be16(&data[rd_idx]);

		if (len > 0) {
			cache_invld(&data[rd_idx + LEN_SZ], len, sync);
			*buf = &data[rd_idx + LEN_SZ];
			return len;
		}
	}

	/* If len == 0 or message could not fit at the end of the buffer it indicates
	 * that buffer wrapped.
	 */
	rd_idx = 0;
	set_rd_idx(pb, rd_idx, sync);
	if (wr_idx == rd_idx) {
		return 0;
	}

	cache_invld(&data[rd_idx], LEN_SZ, sync);
	uint16_t len = sys_get_be16(&data[rd_idx]);

	cache_invld(&data[rd_idx + LEN_SZ], len, sync);
	*buf = &data[rd_idx + LEN_SZ];

	return len;
}

void spsc_pbuf_free(struct spsc_pbuf *pb, uint16_t len)
{
	/* Length of the buffer and flags are immutable - avoid reloading. */
	const bool sync = is_Synchronized(pb);
	const uint32_t pblen = pb->common.len * sizeof(uint32_t);
	uint32_t rd_idx = get_rd_idx(pb, sync) + ROUND_UP(len + LEN_SZ, sizeof(uint32_t));
	uint8_t *data = (uint8_t *)get_data(pb, sync);

	/* Handle wrapping if message is at the end of the buffer and no marker
	 * can be placed.
	 */
	if (rd_idx + LEN_SZ > pblen) {
		rd_idx = 0;
	} else {
		rd_idx = idx_cut(pblen, rd_idx);
		/* Check if wrapping marker is present. If yes, rewind rd_idx to 0
		 * to avoid blocking space.
		 */
		if (rd_idx != get_wr_idx(pb, sync)) {
			cache_invld(&data[rd_idx], LEN_SZ, sync);
			if (sys_get_be16(&data[rd_idx]) == 0) {
				rd_idx = 0;
			}
		}
	}

	barrier_dmem_fence_full();
	set_rd_idx(pb, rd_idx, sync);
}

int spsc_pbuf_read(struct spsc_pbuf *pb, char *buf, uint16_t len)
{
	char *pkt;
	uint16_t plen = spsc_pbuf_claim(pb, &pkt);

	if (plen == 0) {
		return 0;
	}

	if (buf == NULL) {
		return plen;
	}

	if (len < plen) {
		return -ENOMEM;
	}

	memcpy(buf, pkt, plen);
	spsc_pbuf_free(pb, plen);

	return plen;
}

int spsc_pbuf_get_utilization(struct spsc_pbuf *pb)
{
	if (!IS_ENABLED(CONFIG_SPSC_PBUF_UTILIZATION)) {
		return -ENOTSUP;
	}

	const bool sync = is_Synchronized(pb);

	cache_invld(&pb->common.flags, sizeof(pb->common.flags), sync);

	if (!(pb->common.flags & SPSC_PBUF_UTILIZATION)) {
		return -ENOTSUP;
	}

	return GET_UTILIZATION(pb->common.flags);
}
